WITH src AS (SELECT * FROM payments WHERE TO_DATE(paid_at) < '2023-05-01'), method_group_summary AS (SELECT CASE WHEN method IN ('paypal', 'card') THEN 'tier_1' ELSE 'other' END AS method_group, MIN(paid_at) AS first_paid_at, AVG(amount) AS avg_amount FROM src GROUP BY CASE WHEN method IN ('paypal', 'card') THEN 'tier_1' ELSE 'other' END) SELECT * FROM method_group_summary WHERE avg_amount > 680 ORDER BY avg_amount;
